$$
import json
import hashlib

"""Deterministic criteria engine shared by the payer service (mock mode) and the
Snowflake stored procedures (the generator embeds this file in the SP body).

Rules (PRD 8.6):
- The LLM only extracts facts. Thresholds are applied here, never by a model.
- Three-valued logic: MET / NOT_MET / UNKNOWN.
- AUTO_APPROVE only when the tree is MET and every leaf that satisfies it has a
  verified citation. Anything uncertain becomes PEND. A NOT_MET tree becomes
  RECOMMEND_DENY only if a failing leaf is marked RECOMMEND_DENY; that outcome
  goes to a clinician and is never a denial by itself.

Keep this module standard-library only and free of double dollar signs so it can be
embedded in a Snowflake Python stored procedure.
"""

import re

MET, NOT_MET, UNKNOWN = "MET", "NOT_MET", "UNKNOWN"
AUTO_APPROVE, PEND, RECOMMEND_DENY = "AUTO_APPROVE", "PEND", "RECOMMEND_DENY"


def normalize_space(text):
    return re.sub(r"\s+", " ", text or "").strip()


def verify_quote(quote, doc_text):
    """A citation is valid only if the quote is an exact substring of the
    document (whitespace-normalized). Paraphrases fail on purpose."""
    if not quote or not doc_text:
        return False
    return normalize_space(quote) in normalize_space(doc_text)


def _to_bool(value):
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        v = value.strip().lower()
        if v in ("true", "yes", "y", "1"):
            return True
        if v in ("false", "no", "n", "0"):
            return False
    if isinstance(value, (int, float)):
        return bool(value)
    return None


def _to_num(value):
    if isinstance(value, bool):
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def compare(value, operator, threshold):
    """Return MET / NOT_MET / UNKNOWN for one leaf."""
    if value is None or value == "":
        return UNKNOWN
    if isinstance(threshold, bool) or (isinstance(threshold, str) and threshold.lower() in ("true", "false")):
        left, right = _to_bool(value), _to_bool(threshold)
        if left is None or right is None:
            return UNKNOWN
        ok = left == right if operator == "=" else left != right
        return MET if ok else NOT_MET
    left, right = _to_num(value), _to_num(threshold)
    if left is None or right is None:
        if operator == "=":
            return MET if str(value).strip().lower() == str(threshold).strip().lower() else NOT_MET
        return UNKNOWN
    ops = {
        ">=": left >= right, ">": left > right, "<=": left <= right,
        "<": left < right, "=": left == right, "!=": left != right,
    }
    if operator not in ops:
        return UNKNOWN
    return MET if ops[operator] else NOT_MET


def _combine(node_type, statuses):
    if node_type == "AND":
        if NOT_MET in statuses:
            return NOT_MET
        return MET if statuses and all(s == MET for s in statuses) else UNKNOWN
    if node_type == "OR":
        if MET in statuses:
            return MET
        return NOT_MET if statuses and all(s == NOT_MET for s in statuses) else UNKNOWN
    raise ValueError("unknown node type " + str(node_type))


def evaluate(nodes, facts):
    """Evaluate a criteria tree.

    nodes: list of dicts with node_id, parent_node_id, node_type (AND|OR|LEAF),
           label, fact_name, operator, threshold, on_not_met, policy_section_id,
           sort_order.
    facts: {fact_name: {"value": ..., "quote": str|None, "doc_id": str|None,
            "verified": bool, "origin": "auto"|"override"|"manual"}}
    """
    by_id = {n["node_id"]: dict(n) for n in nodes}
    children = {}
    roots = []
    for n in sorted(by_id.values(), key=lambda x: (x.get("sort_order") or 0, x["node_id"])):
        parent = n.get("parent_node_id")
        if parent:
            children.setdefault(parent, []).append(n["node_id"])
        else:
            roots.append(n["node_id"])
    if len(roots) != 1:
        raise ValueError("criteria tree must have exactly one root, found %d" % len(roots))

    results = {}

    def visit(node_id, depth):
        node = by_id[node_id]
        if node["node_type"] == "LEAF":
            fact = facts.get(node.get("fact_name")) or {}
            status = compare(fact.get("value"), node.get("operator"), node.get("threshold"))
            results[node_id] = dict(
                node, depth=depth, status=status, value=fact.get("value"),
                quote=fact.get("quote"), doc_id=fact.get("doc_id"),
                citation_verified=bool(fact.get("verified")), origin=fact.get("origin"),
            )
            return status
        statuses = [visit(c, depth + 1) for c in children.get(node_id, [])]
        status = _combine(node["node_type"], statuses)
        results[node_id] = dict(node, depth=depth, status=status)
        return status

    root_status = visit(roots[0], 0)

    def satisfying_leaves(node_id):
        r = results[node_id]
        if r["node_type"] == "LEAF":
            return [node_id]
        kids = children.get(node_id, [])
        if r["node_type"] == "OR":
            for c in kids:
                if results[c]["status"] == MET:
                    return satisfying_leaves(c)
            return []
        out = []
        for c in kids:
            out.extend(satisfying_leaves(c))
        return out

    def failing_leaves(node_id):
        r = results[node_id]
        if r["node_type"] == "LEAF":
            return [node_id] if r["status"] == NOT_MET else []
        out = []
        for c in children.get(node_id, []):
            if results[c]["status"] == NOT_MET:
                out.extend(failing_leaves(c))
        return out

    leaves = [r for r in results.values() if r["node_type"] == "LEAF"]
    unknown = [r for r in leaves if r["status"] == UNKNOWN]
    missing_info = []
    unmet = []

    if root_status == MET:
        support = [results[i] for i in satisfying_leaves(roots[0])]
        unverified = [r for r in support if not r["citation_verified"]]
        if unverified:
            recommendation = PEND
            missing_info = [
                "Supporting documentation for: %s (section %s)" % (r["label"], r["policy_section_id"])
                for r in unverified
            ]
            reason = "Criteria appear to be met, but %d answer(s) lack a verifiable quote from the submitted records." % len(unverified)
        else:
            recommendation = AUTO_APPROVE
            reason = "All required criteria are met, each backed by a verified quote from the submitted records."
    elif root_status == UNKNOWN:
        recommendation = PEND
        missing_info = [
            "Documentation of: %s (section %s)" % (r["label"], r["policy_section_id"]) for r in unknown
        ]
        reason = "Some criteria could not be assessed from the submitted information."
    else:
        failing = [results[i] for i in failing_leaves(roots[0])]
        unmet = [
            "%s (section %s): documented value %s" % (r["label"], r["policy_section_id"], _fmt(r["value"]))
            for r in failing
        ]
        if any(r.get("on_not_met") == RECOMMEND_DENY for r in failing):
            recommendation = RECOMMEND_DENY
            reason = "The documented values do not meet the policy criteria. A clinician must review before any denial."
        else:
            recommendation = PEND
            missing_info = [
                "Documentation that would satisfy: %s (section %s)" % (r["label"], r["policy_section_id"])
                for r in failing
            ]
            reason = "Criteria are not yet met; additional documentation may satisfy them."

    ordered = [results[n["node_id"]] for n in sorted(by_id.values(), key=lambda x: (x.get("sort_order") or 0))]
    return {
        "recommendation": recommendation,
        "root_status": root_status,
        "reason_text": reason,
        "missing_info": missing_info,
        "unmet": unmet,
        "criteria": [_public(r) for r in ordered],
    }


def _fmt(value):
    if value is None:
        return "not documented"
    if isinstance(value, bool):
        return "yes" if value else "no"
    return str(value)


def _public(r):
    keys = ("node_id", "parent_node_id", "node_type", "label", "fact_name", "operator", "threshold",
            "on_not_met", "policy_section_id", "depth", "status", "value", "quote", "doc_id",
            "citation_verified", "origin")
    return {k: r.get(k) for k in keys}


# Shared helpers embedded into the Python stored procedures by build_sql.py.
import json as _json


def q(session, sql, params=None):
    rows = session.sql(sql, params=params or []).collect()
    out = []
    for r in rows:
        d = {}
        for k, v in r.as_dict().items():
            if isinstance(v, str) and v[:1] in ("{", "["):
                try:
                    v = _json.loads(v)
                except ValueError:
                    pass
            d[k.lower()] = v
        out.append(d)
    return out


def scalar(session, sql, params=None):
    return session.sql(sql, params=params or []).collect()[0][0]


def _iso(v):
    return v.isoformat() if hasattr(v, "isoformat") else v


def load_nodes(session, policy_doc_id):
    rows = q(session,
             "SELECT node_id, parent_node_id, node_type, label, fact_name, operator, threshold, on_not_met, "
             "policy_section_id, sort_order FROM PAYER.POLICY_CRITERIA WHERE policy_doc_id = ? ORDER BY sort_order",
             [policy_doc_id])
    for r in rows:
        t = r.get("threshold")
        if isinstance(t, str):
            try:
                r["threshold"] = _json.loads(t)
            except ValueError:
                pass
    return rows


def decide(session, pa_id, admin_ref, code, by, role, reason_text, request_text=None):
    approve = code in ("A1", "A6")
    auth = "AUTH-%s" % scalar(session, "SELECT PAYER.SEQ_AUTH.NEXTVAL") if approve else None
    session.sql(
        "INSERT INTO PAYER.DECISION (pa_id, review_action_code, auth_number, admin_ref_number, auth_period_start, "
        "auth_period_end, reason_text, request_text, decided_by, decider_role, ai_assisted) "
        "SELECT ?, ?, ?, ?, IFF(?, CURRENT_DATE(), NULL), IFF(?, DATEADD(day, 90, CURRENT_DATE()), NULL), ?, ?, ?, ?, TRUE",
        params=[pa_id, code, auth, admin_ref, approve, approve, reason_text, request_text, by, role]).collect()
    row = q(session, "SELECT * FROM PAYER.DECISION WHERE pa_id = ? ORDER BY decided_at DESC LIMIT 1", [pa_id])[0]
    return row


def result_of(pa, decision, result):
    return {
        "pa_id": pa["pa_id"], "claim_id": pa["claim_id"], "status": pa["status"],
        "recommendation": pa["recommendation"], "review_action": decision["review_action_code"],
        "auth_number": decision["auth_number"], "admin_ref": decision["admin_ref_number"],
        "period_start": _iso(decision["auth_period_start"]), "period_end": _iso(decision["auth_period_end"]),
        "reason_text": decision["reason_text"], "request_text": decision["request_text"],
        "missing_info": pa.get("missing_info") or [], "unmet": pa.get("unmet") or [],
        "criteria": (result or {}).get("criteria") or pa.get("criteria") or [],
        "sla_due_at": _iso(pa["sla_due_at"]), "decided_by": decision["decided_by"],
        "provider_org_npi": pa.get("provider_org_npi"), "patient_id": pa["patient_id"], "member_id": pa["member_id"],
    }



def run(session, request):
    req = json.loads(request)
    member = q(session,
        "SELECT m.plan_id, p.line_of_business FROM PAYER.MEMBER_ELIGIBILITY m "
        "JOIN PAYER.PAYER_PLAN p ON p.plan_id = m.plan_id "
        "WHERE m.member_id = ? AND m.status = 'active' "
        "AND CURRENT_DATE() BETWEEN m.eff_start AND COALESCE(m.eff_end, '9999-12-31'::DATE)", [req["member_id"]])
    if not member:
        return {"error": "no-active-coverage", "message": "No active coverage for member %s" % req["member_id"]}
    plan_id, lob = member[0]["plan_id"], member[0]["line_of_business"]
    rule = q(session,
        "SELECT * FROM PAYER.SERVICE_PA_RULES WHERE service_code = ? AND (plan_id = ? OR plan_id IS NULL) "
        "AND CURRENT_DATE() >= effective_from AND (effective_to IS NULL OR CURRENT_DATE() <= effective_to) "
        "ORDER BY IFF(plan_id IS NULL, 1, 0) LIMIT 1", [req["service_code"], plan_id])
    rule = rule[0] if rule else None

    existing = None
    if req.get("related_pa_id"):
        rows = q(session, "SELECT * FROM PAYER.PA_REQUEST WHERE pa_id = ?", [req["related_pa_id"]])
        existing = rows[0] if rows else None
    pa_id = existing["pa_id"] if existing else "PA-%s" % scalar(session, "SELECT PAYER.SEQ_PA.NEXTVAL")
    version = (existing["version"] + 1) if existing else 1
    admin_ref = existing["admin_ref"] if existing else "REF-%s" % scalar(session, "SELECT PAYER.SEQ_REF.NEXTVAL")

    for d in req.get("documents", []):
        session.sql(
            "MERGE INTO PAYER.SUBMITTED_DOCUMENT t USING (SELECT ? AS pa_id, ? AS doc_id, ? AS title, "
            "TRY_TO_DATE(?) AS encounter_date, ? AS text) s ON t.pa_id = s.pa_id AND t.doc_id = s.doc_id "
            "WHEN MATCHED THEN UPDATE SET text = s.text, title = s.title "
            "WHEN NOT MATCHED THEN INSERT (pa_id, doc_id, title, encounter_date, text) "
            "VALUES (s.pa_id, s.doc_id, s.title, s.encounter_date, s.text)",
            params=[pa_id, d["doc_id"], d.get("title"), d.get("encounter_date"), d.get("text")]).collect()
    docs = {r["doc_id"]: r["text"] for r in q(session, "SELECT doc_id, text FROM PAYER.SUBMITTED_DOCUMENT WHERE pa_id = ?", [pa_id])}

    facts = {}
    for name, ans in (req.get("answers") or {}).items():
        facts[name] = dict(ans, verified=verify_quote(ans.get("quote"), docs.get(ans.get("doc_id"))))

    if not rule or not rule["pa_required"]:
        result = {"recommendation": AUTO_APPROVE, "reason_text": "Prior authorization is not required for this service.",
                  "criteria": [], "missing_info": [], "unmet": []}
    else:
        nodes = load_nodes(session, rule["policy_doc_id"])
        result = evaluate(nodes, facts)

    rec = result["recommendation"]
    status = {"AUTO_APPROVE": "APPROVED", "PEND": "PENDED", "RECOMMEND_DENY": "CLINICIAN_REVIEW"}[rec]
    sla_hours = 72 if req.get("priority") == "expedited" else 168

    if existing:
        session.sql(
            "UPDATE PAYER.PA_REQUEST SET status = ?, recommendation = ?, reason_text = ?, missing_info = PARSE_JSON(?), "
            "unmet = PARSE_JSON(?), criteria = PARSE_JSON(?), version = ?, updated_at = CURRENT_TIMESTAMP() WHERE pa_id = ?",
            params=[status, rec, result["reason_text"], json.dumps(result["missing_info"]), json.dumps(result["unmet"]),
                    json.dumps(result["criteria"]), version, pa_id]).collect()
    else:
        session.sql(
            "INSERT INTO PAYER.PA_REQUEST (pa_id, claim_id, patient_id, member_id, plan_id, line_of_business, ordering_npi, "
            "provider_org_npi, service_code, code_system, service_display, policy_doc_id, questionnaire_id, icd10_codes, "
            "priority, coverage_assertion_id, status, recommendation, reason_text, missing_info, unmet, criteria, admin_ref, "
            "version, submitted_at, sla_due_at, updated_at) "
            "SELECT ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, PARSE_JSON(?), ?, ?, ?, ?, ?, PARSE_JSON(?), PARSE_JSON(?), "
            "PARSE_JSON(?), ?, 1, CURRENT_TIMESTAMP(), DATEADD(hour, ?, CURRENT_TIMESTAMP()), CURRENT_TIMESTAMP()",
            params=[pa_id, req["claim_id"], req["patient_id"], req["member_id"], plan_id, lob, req.get("ordering_npi"),
                    req.get("provider_org_npi"), req["service_code"], req.get("code_system"), req.get("service_display"),
                    rule["policy_doc_id"] if rule else None, req.get("questionnaire_id"), json.dumps(req.get("icd10", [])),
                    req.get("priority", "standard"), req.get("coverage_assertion_id"), status, rec, result["reason_text"],
                    json.dumps(result["missing_info"]), json.dumps(result["unmet"]), json.dumps(result["criteria"]),
                    admin_ref, sla_hours]).collect()

    answers = req.get("answers") or {}
    auto = sum(1 for a in answers.values() if a.get("origin") == "auto")
    session.sql("INSERT INTO PAYER.QUESTIONNAIRE_RESPONSE (pa_id, version, answers, ai_prefill_pct) SELECT ?, ?, PARSE_JSON(?), ?",
                params=[pa_id, version, json.dumps(answers), (auto / len(answers)) if answers else 0]).collect()
    session.sql(
        "INSERT INTO AI.CLINICAL_REVIEW (pa_id, version, node_id, node_type, label, fact_name, fact_value, status, "
        "evidence_quote, evidence_doc_id, policy_section_id, citation_verified, origin) "
        "SELECT ?, ?, c.value:node_id::STRING, c.value:node_type::STRING, c.value:label::STRING, c.value:fact_name::STRING, "
        "c.value:value, c.value:status::STRING, c.value:quote::STRING, c.value:doc_id::STRING, "
        "c.value:policy_section_id::STRING, c.value:citation_verified::BOOLEAN, c.value:origin::STRING "
        "FROM TABLE(FLATTEN(INPUT => PARSE_JSON(?))) c",
        params=[pa_id, version, json.dumps(result["criteria"])]).collect()
    session.sql(
        "INSERT INTO AI.AI_RECOMMENDATION_AUDIT (pa_id, agent_name, model, policy_version, input_hash, output, recommendation, ai_assisted) "
        "SELECT ?, 'CRITERIA_ENGINE', 'deterministic', ?, ?, PARSE_JSON(?), ?, ?",
        params=[pa_id, rule["policy_doc_id"] if rule else None, hashlib.sha256(request.encode()).hexdigest(),
                json.dumps(result), rec, auto > 0]).collect()

    if rec == AUTO_APPROVE:
        decision = decide(session, pa_id, admin_ref, "A1", "SYSTEM", "SYSTEM", result["reason_text"])
    elif rec == PEND:
        decision = decide(session, pa_id, admin_ref, "A4", "SYSTEM", "SYSTEM", result["reason_text"],
                          "; ".join(result["missing_info"]))
    else:
        decision = decide(session, pa_id, admin_ref, "A4", "SYSTEM", "SYSTEM", "Pended for clinical review. " + result["reason_text"],
                          "A clinician is reviewing this request. No action is needed unless more records are available.")
    pa = q(session, "SELECT * FROM PAYER.PA_REQUEST WHERE pa_id = ?", [pa_id])[0]
    return result_of(pa, decision, result)
$$;

-- ---------------------------------------------------------------------------
-- PAYER.SP_RECORD_DECISION — clinician actions from the payer workbench.
-- Only MEDICAL_DIRECTOR may issue A3, with a named signer and a specific reason.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE PAYER.SP_RECORD_DECISION(
    PA_ID STRING, ACTION STRING, REVIEWER STRING, REVIEWER_ROLE STRING, REASON_TEXT STRING, REQUEST_TEXT STRING)
RETURNS VARIANT
LANGUAGE PYTHON
RUNTIME_VERSION = '3.11'
PACKAGES = ('snowflake-snowpark-python')
HANDLER = 'run'
EXECUTE AS OWNER
AS
$$
import json

# Shared helpers embedded into the Python stored procedures by build_sql.py.
import json as _json


def q(session, sql, params=None):
    rows = session.sql(sql, params=params or []).collect()
    out = []
    for r in rows:
        d = {}
        for k, v in r.as_dict().items():
            if isinstance(v, str) and v[:1] in ("{", "["):
                try:
                    v = _json.loads(v)
                except ValueError:
                    pass
            d[k.lower()] = v
        out.append(d)
    return out


def scalar(session, sql, params=None):
    return session.sql(sql, params=params or []).collect()[0][0]


def _iso(v):
    return v.isoformat() if hasattr(v, "isoformat") else v


def load_nodes(session, policy_doc_id):
    rows = q(session,
             "SELECT node_id, parent_node_id, node_type, label, fact_name, operator, threshold, on_not_met, "
             "policy_section_id, sort_order FROM PAYER.POLICY_CRITERIA WHERE policy_doc_id = ? ORDER BY sort_order",
             [policy_doc_id])
    for r in rows:
        t = r.get("threshold")
        if isinstance(t, str):
            try:
                r["threshold"] = _json.loads(t)
            except ValueError:
                pass
    return rows


def decide(session, pa_id, admin_ref, code, by, role, reason_text, request_text=None):
    approve = code in ("A1", "A6")
    auth = "AUTH-%s" % scalar(session, "SELECT PAYER.SEQ_AUTH.NEXTVAL") if approve else None
    session.sql(
        "INSERT INTO PAYER.DECISION (pa_id, review_action_code, auth_number, admin_ref_number, auth_period_start, "
        "auth_period_end, reason_text, request_text, decided_by, decider_role, ai_assisted) "
        "SELECT ?, ?, ?, ?, IFF(?, CURRENT_DATE(), NULL), IFF(?, DATEADD(day, 90, CURRENT_DATE()), NULL), ?, ?, ?, ?, TRUE",
        params=[pa_id, code, auth, admin_ref, approve, approve, reason_text, request_text, by, role]).collect()
    row = q(session, "SELECT * FROM PAYER.DECISION WHERE pa_id = ? ORDER BY decided_at DESC LIMIT 1", [pa_id])[0]
    return row


def result_of(pa, decision, result):
    return {
        "pa_id": pa["pa_id"], "claim_id": pa["claim_id"], "status": pa["status"],
        "recommendation": pa["recommendation"], "review_action": decision["review_action_code"],
        "auth_number": decision["auth_number"], "admin_ref": decision["admin_ref_number"],
        "period_start": _iso(decision["auth_period_start"]), "period_end": _iso(decision["auth_period_end"]),
        "reason_text": decision["reason_text"], "request_text": decision["request_text"],
        "missing_info": pa.get("missing_info") or [], "unmet": pa.get("unmet") or [],
        "criteria": (result or {}).get("criteria") or pa.get("criteria") or [],
        "sla_due_at": _iso(pa["sla_due_at"]), "decided_by": decision["decided_by"],
        "provider_org_npi": pa.get("provider_org_npi"), "patient_id": pa["patient_id"], "member_id": pa["member_id"],
    }



def run(session, pa_id, action, reviewer, role, reason_text, request_text):
    rows = q(session, "SELECT * FROM PAYER.PA_REQUEST WHERE pa_id = ? AND NOT is_historical", [pa_id])
    if not rows:
        raise ValueError("Unknown request %s" % pa_id)
    pa = rows[0]
    if action == "DENY":
        if role != "MEDICAL_DIRECTOR":
            raise PermissionError("Only a medical director can issue a denial (A3).")
        if not reviewer or not reason_text:
            raise ValueError("A denial needs a named signer and a specific reason.")
        status, code = "DENIED", "A3"
    elif action == "APPROVE":
        status, code = "APPROVED", "A1"
        reason_text = reason_text or "Approved after clinical review."
    elif action == "PEND":
        status, code = "PENDED", "A4"
        reason_text = reason_text or "More information requested."
        request_text = request_text or reason_text
    else:
        raise ValueError("action must be APPROVE, PEND or DENY")
    session.sql("UPDATE PAYER.PA_REQUEST SET status = ?, updated_at = CURRENT_TIMESTAMP() WHERE pa_id = ?",
                params=[status, pa_id]).collect()
    decision = decide(session, pa_id, pa["admin_ref"], code, reviewer, role, reason_text,
                      request_text if code == "A4" else None)
    session.sql(
        "INSERT INTO AI.AI_RECOMMENDATION_AUDIT (pa_id, agent_name, recommendation, output, ai_assisted, human_actor) "
        "SELECT ?, 'HUMAN', ?, PARSE_JSON(?), TRUE, ?",
        params=[pa_id, pa["recommendation"], json.dumps({"action": action, "reason": reason_text, "role": role}), reviewer]).collect()
    pa = q(session, "SELECT * FROM PAYER.PA_REQUEST WHERE pa_id = ?", [pa_id])[0]
    return result_of(pa, decision, None)
$$;

-- ---------------------------------------------------------------------------
-- PAYER.SP_COMPLETENESS — provider-side pre-check before submission (FR-4.6).
-- FACTS is a JSON object {fact: {value, quote, doc_id, verified, origin}}.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE PAYER.SP_COMPLETENESS(QUESTIONNAIRE_ID STRING, FACTS STRING)
RETURNS VARIANT
LANGUAGE PYTHON
RUNTIME_VERSION = '3.11'
PACKAGES = ('snowflake-snowpark-python')
HANDLER = 'run'
EXECUTE AS OWNER
AS
$$
import json

"""Deterministic criteria engine shared by the payer service (mock mode) and the
Snowflake stored procedures (the generator embeds this file in the SP body).

Rules (PRD 8.6):
- The LLM only extracts facts. Thresholds are applied here, never by a model.
- Three-valued logic: MET / NOT_MET / UNKNOWN.
- AUTO_APPROVE only when the tree is MET and every leaf that satisfies it has a
  verified citation. Anything uncertain becomes PEND. A NOT_MET tree becomes
  RECOMMEND_DENY only if a failing leaf is marked RECOMMEND_DENY; that outcome
  goes to a clinician and is never a denial by itself.

Keep this module standard-library only and free of double dollar signs so it can be
embedded in a Snowflake Python stored procedure.
"""

import re

MET, NOT_MET, UNKNOWN = "MET", "NOT_MET", "UNKNOWN"
AUTO_APPROVE, PEND, RECOMMEND_DENY = "AUTO_APPROVE", "PEND", "RECOMMEND_DENY"


def normalize_space(text):
    return re.sub(r"\s+", " ", text or "").strip()


def verify_quote(quote, doc_text):
    """A citation is valid only if the quote is an exact substring of the
    document (whitespace-normalized). Paraphrases fail on purpose."""
    if not quote or not doc_text:
        return False
    return normalize_space(quote) in normalize_space(doc_text)


def _to_bool(value):
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        v = value.strip().lower()
        if v in ("true", "yes", "y", "1"):
            return True
        if v in ("false", "no", "n", "0"):
            return False
    if isinstance(value, (int, float)):
        return bool(value)
    return None


def _to_num(value):
    if isinstance(value, bool):
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def compare(value, operator, threshold):
    """Return MET / NOT_MET / UNKNOWN for one leaf."""
    if value is None or value == "":
        return UNKNOWN
    if isinstance(threshold, bool) or (isinstance(threshold, str) and threshold.lower() in ("true", "false")):
        left, right = _to_bool(value), _to_bool(threshold)
        if left is None or right is None:
            return UNKNOWN
        ok = left == right if operator == "=" else left != right
        return MET if ok else NOT_MET
    left, right = _to_num(value), _to_num(threshold)
    if left is None or right is None:
        if operator == "=":
            return MET if str(value).strip().lower() == str(threshold).strip().lower() else NOT_MET
        return UNKNOWN
    ops = {
        ">=": left >= right, ">": left > right, "<=": left <= right,
        "<": left < right, "=": left == right, "!=": left != right,
    }
    if operator not in ops:
        return UNKNOWN
    return MET if ops[operator] else NOT_MET


def _combine(node_type, statuses):
    if node_type == "AND":
        if NOT_MET in statuses:
            return NOT_MET
        return MET if statuses and all(s == MET for s in statuses) else UNKNOWN
    if node_type == "OR":
        if MET in statuses:
            return MET
        return NOT_MET if statuses and all(s == NOT_MET for s in statuses) else UNKNOWN
    raise ValueError("unknown node type " + str(node_type))


def evaluate(nodes, facts):
    """Evaluate a criteria tree.

    nodes: list of dicts with node_id, parent_node_id, node_type (AND|OR|LEAF),
           label, fact_name, operator, threshold, on_not_met, policy_section_id,
           sort_order.
    facts: {fact_name: {"value": ..., "quote": str|None, "doc_id": str|None,
            "verified": bool, "origin": "auto"|"override"|"manual"}}
    """
    by_id = {n["node_id"]: dict(n) for n in nodes}
    children = {}
    roots = []
    for n in sorted(by_id.values(), key=lambda x: (x.get("sort_order") or 0, x["node_id"])):
        parent = n.get("parent_node_id")
        if parent:
            children.setdefault(parent, []).append(n["node_id"])
        else:
            roots.append(n["node_id"])
    if len(roots) != 1:
        raise ValueError("criteria tree must have exactly one root, found %d" % len(roots))

    results = {}

    def visit(node_id, depth):
        node = by_id[node_id]
        if node["node_type"] == "LEAF":
            fact = facts.get(node.get("fact_name")) or {}
            status = compare(fact.get("value"), node.get("operator"), node.get("threshold"))
            results[node_id] = dict(
                node, depth=depth, status=status, value=fact.get("value"),
                quote=fact.get("quote"), doc_id=fact.get("doc_id"),
                citation_verified=bool(fact.get("verified")), origin=fact.get("origin"),
            )
            return status
        statuses = [visit(c, depth + 1) for c in children.get(node_id, [])]
        status = _combine(node["node_type"], statuses)
        results[node_id] = dict(node, depth=depth, status=status)
        return status

    root_status = visit(roots[0], 0)

    def satisfying_leaves(node_id):
        r = results[node_id]
        if r["node_type"] == "LEAF":
            return [node_id]
        kids = children.get(node_id, [])
        if r["node_type"] == "OR":
            for c in kids:
                if results[c]["status"] == MET:
                    return satisfying_leaves(c)
            return []
        out = []
        for c in kids:
            out.extend(satisfying_leaves(c))
        return out

    def failing_leaves(node_id):
        r = results[node_id]
        if r["node_type"] == "LEAF":
            return [node_id] if r["status"] == NOT_MET else []
        out = []
        for c in children.get(node_id, []):
            if results[c]["status"] == NOT_MET:
                out.extend(failing_leaves(c))
        return out

    leaves = [r for r in results.values() if r["node_type"] == "LEAF"]
    unknown = [r for r in leaves if r["status"] == UNKNOWN]
    missing_info = []
    unmet = []

    if root_status == MET:
        support = [results[i] for i in satisfying_leaves(roots[0])]
        unverified = [r for r in support if not r["citation_verified"]]
        if unverified:
            recommendation = PEND
            missing_info = [
                "Supporting documentation for: %s (section %s)" % (r["label"], r["policy_section_id"])
                for r in unverified
            ]
            reason = "Criteria appear to be met, but %d answer(s) lack a verifiable quote from the submitted records." % len(unverified)
        else:
            recommendation = AUTO_APPROVE
            reason = "All required criteria are met, each backed by a verified quote from the submitted records."
    elif root_status == UNKNOWN:
        recommendation = PEND
        missing_info = [
            "Documentation of: %s (section %s)" % (r["label"], r["policy_section_id"]) for r in unknown
        ]
        reason = "Some criteria could not be assessed from the submitted information."
    else:
        failing = [results[i] for i in failing_leaves(roots[0])]
        unmet = [
            "%s (section %s): documented value %s" % (r["label"], r["policy_section_id"], _fmt(r["value"]))
            for r in failing
        ]
        if any(r.get("on_not_met") == RECOMMEND_DENY for r in failing):
            recommendation = RECOMMEND_DENY
            reason = "The documented values do not meet the policy criteria. A clinician must review before any denial."
        else:
            recommendation = PEND
            missing_info = [
                "Documentation that would satisfy: %s (section %s)" % (r["label"], r["policy_section_id"])
                for r in failing
            ]
            reason = "Criteria are not yet met; additional documentation may satisfy them."

    ordered = [results[n["node_id"]] for n in sorted(by_id.values(), key=lambda x: (x.get("sort_order") or 0))]
    return {
        "recommendation": recommendation,
        "root_status": root_status,
        "reason_text": reason,
        "missing_info": missing_info,
        "unmet": unmet,
        "criteria": [_public(r) for r in ordered],
    }


def _fmt(value):
    if value is None:
        return "not documented"
    if isinstance(value, bool):
        return "yes" if value else "no"
    return str(value)


def _public(r):
    keys = ("node_id", "parent_node_id", "node_type", "label", "fact_name", "operator", "threshold",
            "on_not_met", "policy_section_id", "depth", "status", "value", "quote", "doc_id",
            "citation_verified", "origin")
    return {k: r.get(k) for k in keys}


# Shared helpers embedded into the Python stored procedures by build_sql.py.
import json as _json


def q(session, sql, params=None):
    rows = session.sql(sql, params=params or []).collect()
    out = []
    for r in rows:
        d = {}
        for k, v in r.as_dict().items():
            if isinstance(v, str) and v[:1] in ("{", "["):
                try:
                    v = _json.loads(v)
                except ValueError:
                    pass
            d[k.lower()] = v
        out.append(d)
    return out


def scalar(session, sql, params=None):
    return session.sql(sql, params=params or []).collect()[0][0]


def _iso(v):
    return v.isoformat() if hasattr(v, "isoformat") else v


def load_nodes(session, policy_doc_id):
    rows = q(session,
             "SELECT node_id, parent_node_id, node_type, label, fact_name, operator, threshold, on_not_met, "
             "policy_section_id, sort_order FROM PAYER.POLICY_CRITERIA WHERE policy_doc_id = ? ORDER BY sort_order",
             [policy_doc_id])
    for r in rows:
        t = r.get("threshold")
        if isinstance(t, str):
            try:
                r["threshold"] = _json.loads(t)
            except ValueError:
                pass
    return rows


def decide(session, pa_id, admin_ref, code, by, role, reason_text, request_text=None):
    approve = code in ("A1", "A6")
    auth = "AUTH-%s" % scalar(session, "SELECT PAYER.SEQ_AUTH.NEXTVAL") if approve else None
    session.sql(
        "INSERT INTO PAYER.DECISION (pa_id, review_action_code, auth_number, admin_ref_number, auth_period_start, "
        "auth_period_end, reason_text, request_text, decided_by, decider_role, ai_assisted) "
        "SELECT ?, ?, ?, ?, IFF(?, CURRENT_DATE(), NULL), IFF(?, DATEADD(day, 90, CURRENT_DATE()), NULL), ?, ?, ?, ?, TRUE",
        params=[pa_id, code, auth, admin_ref, approve, approve, reason_text, request_text, by, role]).collect()
    row = q(session, "SELECT * FROM PAYER.DECISION WHERE pa_id = ? ORDER BY decided_at DESC LIMIT 1", [pa_id])[0]
    return row


def result_of(pa, decision, result):
    return {
        "pa_id": pa["pa_id"], "claim_id": pa["claim_id"], "status": pa["status"],
        "recommendation": pa["recommendation"], "review_action": decision["review_action_code"],
        "auth_number": decision["auth_number"], "admin_ref": decision["admin_ref_number"],
        "period_start": _iso(decision["auth_period_start"]), "period_end": _iso(decision["auth_period_end"]),
        "reason_text": decision["reason_text"], "request_text": decision["request_text"],
        "missing_info": pa.get("missing_info") or [], "unmet": pa.get("unmet") or [],
        "criteria": (result or {}).get("criteria") or pa.get("criteria") or [],
        "sla_due_at": _iso(pa["sla_due_at"]), "decided_by": decision["decided_by"],
        "provider_org_npi": pa.get("provider_org_npi"), "patient_id": pa["patient_id"], "member_id": pa["member_id"],
    }



def run(session, questionnaire_id, facts):
    rows = q(session, "SELECT MAX(policy_doc_id) AS policy FROM PAYER.SERVICE_PA_RULES WHERE questionnaire_id = ?", [questionnaire_id])
    policy = rows[0]["policy"] if rows else None
    if not policy:
        return None
    result = evaluate(load_nodes(session, policy), json.loads(facts))
    result["policy_doc_id"] = policy
    return result
$$;

